package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.CanonicalJson;
import com.lianxibu.site.service.jobs.GenerationFlowService.Stage;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.JsonNode;

class FrozenApplicationContextTest {
 static String context(Stage stage){String target=stage.report()?"{\"kind\":\"report\",\"id\":\"fictional-report\",\"base_revision\":3}":stage.analysis()?"{\"kind\":\""+stage.name().toLowerCase().replace("_analysis","")+"\",\"id\":\"fictional-analysis\",\"base_revision\":null}":"null";return "{\"schema_version\":\"frozen-application-context-v1\",\"stage\":\""+stage.name().toLowerCase()+"\",\"generation\":1,\"target_content\":"+target+",\"target_entity_id\":"+(stage.analysis()?"\"fictional-entity\"":"null")+",\"period_start\":"+(stage.report()?"\"2025-12-31T16:00:00.000000Z\"":"null")+",\"period_end\":"+(stage.report()?"\"2026-01-01T16:00:00.000000Z\"":"null")+",\"item_ids\":[\"fictional-item\"],\"candidates_by_item\":[{\"item_id\":\"fictional-item\",\"entity_ids\":[\"fictional-entity\"]}],\"eligible_high_value_item_ids\":[\"fictional-item\"],\"allowed_citation_ids\":[\"fictional-citation\"],\"version_eligible_item_ids\":[\"fictional-item\"],\"reference_targets\":[{\"kind\":\"article_revision\",\"id\":\"fictional-citation\"}],\"references_complete\":true}";}
 @Test void closedContextBindsEveryApplicabilityFieldAndDoesNotBorrowCurrentData(){var c=FrozenApplicationContext.fromJson(CanonicalJson.parse(context(Stage.DAILY_REPORT)));var input=c.input("fictional-root","fictional-attempt","a".repeat(64),7);assertEquals(Stage.DAILY_REPORT,input.stage());assertEquals(3,input.expectedContentRevision());assertEquals(7,input.expectedRootRevision());assertEquals("fictional-report",c.contentId());assertEquals(java.util.Set.of("fictional-entity"),input.candidatesByItem().get("fictional-item"));assertEquals(1,c.referenceTargets().size());assertTrue(c.referencesComplete());assertEquals(c.json(),FrozenApplicationContext.fromJson(CanonicalJson.parse(c.json())).json());}
 @Test void unknownDuplicateMalformedAndCrossIdentityValuesAreRejected(){for(String bad:new String[]{context(Stage.DAILY_REPORT).replace("\"generation\":1","\"generation\":1,\"raw_prompt\":\"fictional\""),context(Stage.DAILY_REPORT).replace("[\"fictional-item\"]","[\"fictional-item\",\"fictional-item\"]"),context(Stage.DAILY_REPORT).replace("\"kind\":\"report\"","\"kind\":\"agent\""),context(Stage.DAILY_REPORT).replace("2026-01-01T16:00:00.000000Z","2026-01-01T17:00:00.000000Z"),context(Stage.DAILY_REPORT).replace("\"entity_ids\":[\"fictional-entity\"]","\"entity_ids\":[\"\\ud800\"]")})assertThrows(RuntimeException.class,()->FrozenApplicationContext.fromJson(CanonicalJson.parse(bad)));}
 @Test void allFiveResultBranchesAndExactVersionReferencesRoundTrip(){for(var stage:java.util.List.of(Stage.NEWS_DEDUP,Stage.NEWS_VALUE,Stage.AGENT_ANALYSIS,Stage.DAILY_REPORT,Stage.AD_HOC_AI)){var c=FrozenApplicationContext.fromJson(CanonicalJson.parse(context(stage)));assertEquals(stage,c.input("fictional-root","fictional-attempt","a".repeat(64),2).stage());}String ref="{\"kind\":\"content_version\",\"content_kind\":\"report\",\"content_id\":\"fictional-report\",\"revision\":2,\"body_hash\":\""+"b".repeat(64)+"\",\"input_job_id\":\"fictional-old-root\"}";var c=FrozenApplicationContext.fromJson(CanonicalJson.parse(context(Stage.DAILY_REPORT).replace("{\"kind\":\"article_revision\",\"id\":\"fictional-citation\"}",ref)));assertEquals(2,c.referenceTargets().getFirst().path("revision").asInt());assertEquals("fictional-old-root",c.referenceTargets().getFirst().path("input_job_id").asText());}
 @Test void returnedTargetsAreDefensiveAndMissingContextRemainsUnavailable(){var c=FrozenApplicationContext.fromJson(CanonicalJson.parse(context(Stage.NEWS_DEDUP)));((tools.jackson.databind.node.ObjectNode)c.referenceTargets().getFirst()).put("id","changed");assertEquals("fictional-citation",c.referenceTargets().getFirst().path("id").asText());assertThrows(RuntimeException.class,()->FrozenApplicationContext.fromJson(null));var unknown=FrozenApplicationContext.fromJson(CanonicalJson.parse(context(Stage.NEWS_DEDUP).replace("\"references_complete\":true","\"references_complete\":false")));assertFalse(unknown.referencesComplete());}
}
